files.lib/paths.sh:
backup_object_path() {
    local root="$1" tenant="$2"
    printf '%s/%s.bundle\n' "${root%/}" "$tenant"
}
backup_index_path() {
    printf '%s/index.txt\n' "${1%/}"
}

files.tests/paths.sh:
#!/bin/bash
set -eu
source lib/paths.sh
check_space_in_root() {
    local actual
    actual=$(backup_object_path "/srv/night backups/" "tenant-cedar")
    [ "$actual" = "/srv/night backups/tenant-cedar.bundle" ]
}
check_index_name() {
    [ "$(backup_index_path /srv/backups)" = "/srv/backups/index.txt" ]
}
check_space_in_root
check_index_name
